const WORD_WIDTH = 348.1;

function Gold({ id }: { id: string }) {
  return (
    <linearGradient id={id} x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stopColor="#F7E09A" />
      <stop offset="0.55" stopColor="#D9AC55" />
      <stop offset="1" stopColor="#B9862F" />
    </linearGradient>
  );
}

function EmblemShapes({ fill }: { fill: string }) {
  return (
    <>
      <path d={FRAME} fill="none" stroke={fill} strokeWidth="2.2" strokeLinejoin="round" />
      <g fill={fill}>
        {CELLS.map((d, i) => (
          <path key={i} d={d} />
        ))}
      </g>
      <path d={FORK_TINES} fill="none" stroke={fill} strokeWidth="1.5" strokeLinecap="round" />
      <path d={FORK_BODY} fill={fill} />
      <path d={KNIFE} fill={fill} />
    </>
  );
}

/** Square app-style badge: maroon tile, gold emblem, optional wordmark (as in the original). */
export function LogoBadge({ className = "", withWord = true, title = "Malab" }: { className?: string; withWord?: boolean; title?: string }) {
  const id = useId();
  const ws = 0.255;
  const ww = WORD_WIDTH * ws;
  return (
    <svg viewBox="0 0 120 120" role="img" aria-label={title} className={className}>
      <defs>
        <Gold id={id} />
      </defs>
      <rect width="120" height="120" rx="22" fill="#4B0E13" />
      {withWord ? (
        <>
          <g transform="translate(18 6) scale(1.32)">
            <EmblemShapes fill={`url(#${id})`} />
          </g>
          <g transform={`translate(${((120 - ww) / 2).toFixed(2)} 108) scale(${ws})`} fill={`url(#${id})`}>
            <path d={WORD} />
          </g>
        </>
      ) : (
        <g transform="translate(7.5 6.5) scale(1.64)">
          <EmblemShapes fill={`url(#${id})`} />
        </g>
      )}
    </svg>
  );
}

/** Header lockup: emblem tile + MALAB wordmark + SOMALI CUISINE, all vector. */
export function LogoLockup({ className = "" }: { className?: string }) {
  return (
    <span className={`inline-flex items-center gap-3 ${className}`}>
      <LogoBadge withWord={false} className="size-11 shrink-0 sm:size-12" />
      <span className="flex flex-col items-start leading-none">
        <svg viewBox={`0 -72 ${WORD_WIDTH} 74`} aria-hidden="true" className="h-[1.35rem] w-auto text-maroon sm:h-[1.55rem]">
          <path d={WORD} fill="currentColor" />
        </svg>
        <span className="mt-1.5 text-[0.56rem] font-semibold tracking-[0.42em] text-gold-deep uppercase sm:text-[0.6rem]">
          Somali cuisine
        </span>
      </span>
    </span>
  );
}
